export function ConnectorIcon({
  name,
  size = 18,
  className,
}: {
  name: ConnectorName;
  size?: number;
  className?: string;
}) {
  const icon = ICONS[name];
  return (
    <svg
      width={size}
      height={size}
      viewBox={icon.vb}
      fill={icon.fill}
      className={className}
      aria-hidden="true"
      dangerouslySetInnerHTML={{ __html: icon.body }}
    />
  );
}

